"use client";

import Link from "next/link";
import { useParams, useRouter, useSearchParams } from "next/navigation";
import { useEffect, useMemo, useState } from "react";
import {
  Activity, ArrowLeft, Bell, Box, ChartNoAxesCombined, CheckCircle2, ChevronDown,
  ChevronLeft, ChevronRight, CircleHelp, Clock3, Cpu, Download, FileText,
  HardDrive, Info, ListFilter, MoreHorizontal, Play, Plus, Search, Settings2,
  Square, Target, Upload, X,
} from "lucide-react";
import { CartesianGrid, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { canEnter } from "./domain";
import { notify, useResearch } from "./store";
import { COMPUTING_DETAIL_TABS, createComputingSeed, filterComputingTasks, getComputingScenario, getModelTaskScenario, nextComputingStatus, normalizeComputingDetailTab, validateComputeDraft, type ComputingCategory, type ComputingDetailTab, type ComputingStatus, type ComputingTask, type RefineryTemplateId } from "./scientific-computing-domain";
import "./scientific-computing.css";

const STORAGE = "ai4s-scientific-computing-v2";
const statusOptions = ["全部", "运行中", "排队中", "已完成", "失败", "已停止"];
const models = ["催化剂性能预测模型 v2.1", "催化稳定性评估模型 v1.3", "表面性质预测模型 v2.0", "多任务催化剂大模型 v1.5", "反应活性预测模型 v1.2", "材料性质联合模型 v3.0", "反应机理预测模型 v1.1", "选择性预测模型 v2.2"];
type Draft = { name: string; type: string; templateId: RefineryTemplateId; software: string; fileName: string; precision: string; encut: string; kx: string; ky: string; kz: string; ediff: string; resource: string; parallel: string; hours: string; output: string; priority: string; note: string; model: string };
const newDraft = (category: ComputingCategory): Draft => ({ name: "", type: category === "compute" ? "稳态流程模拟" : category === "training" ? "全量训练" : "批量预测", templateId: "generic-refinery-process", software: category === "compute" ? "Aspen HYSYS" : "PyTorch 2.5", fileName: "", precision: category === "training" ? "Validation Loss" : category === "inference" ? "CSV + JSON" : "稳态（推荐）", encut: category === "training" ? "120" : "120", kx: category === "training" ? "64" : category === "inference" ? "256" : "365", ky: category === "training" ? "20" : "145", kz: "3.8", ediff: category === "training" ? "0.001" : category === "inference" ? "0.75" : "0.5", resource: category === "compute" ? "炼化流程模拟节点（32核 / 128GB）" : "GPU 节点（A100 80GB）", parallel: "1", hours: category === "training" ? "48" : "24", output: category === "compute" ? "/data/refinery/simulation/" : category === "training" ? "/data/models/training/" : "/data/models/inference/", priority: "普通", note: "", model: models[0] });
function computeTemplate(type: string): Pick<Draft, "templateId" | "software" | "precision" | "resource"> { if (type === "燃烧与传热CFD") return { templateId: "fired-heater-cfd", software: "OpenFOAM reactingFoam", precision: "瞬态反应流", resource: "HPC CPU节点（128核 / 512GB）" }; if (type === "炼化反应器模拟") return { templateId: "generic-refinery-reactor", software: "Aspen HYSYS Petroleum Refining", precision: "严格动力学", resource: "炼化反应器计算节点（64核 / 256GB）" }; return { templateId: "generic-refinery-process", software: "Aspen HYSYS", precision: "稳态（推荐）", resource: "炼化流程模拟节点（32核 / 128GB）" }; }

function valueOf(value: string | string[] | undefined) { return Array.isArray(value) ? value[0] : value; }
function pathFor(spaceId: string, embedded = false) { return `/research-spaces/${encodeURIComponent(spaceId)}/${embedded ? "activities/computing" : "computing"}`; }
function saveTasks(spaceId: string, tasks: ComputingTask[]) { try { localStorage.setItem(`${STORAGE}:${spaceId}`, JSON.stringify(tasks)); } catch { notify("本地存储不可用，本次修改只保留在当前页面。"); } }
function readTasks(spaceId: string) { try { const raw = localStorage.getItem(`${STORAGE}:${spaceId}`); if (raw) { const parsed: unknown = JSON.parse(raw); if (Array.isArray(parsed)) return parsed as ComputingTask[]; } } catch { /* Keep the demo data when storage is unavailable. */ } return createComputingSeed(spaceId); }
function downloadFile(name: string, text: string, type = "text/plain;charset=utf-8") { const url = URL.createObjectURL(new Blob([text], { type })); const a = document.createElement("a"); a.href = url; a.download = name; a.click(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); }
function stamp() { return new Intl.DateTimeFormat("zh-CN", { year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hour12: false }).format(new Date()).replaceAll("/", "-"); }
function taskReport(task: ComputingTask) { if (task.category !== "compute") return `# ${task.name}\n\n- 任务编号：${task.id}\n- 任务类型：${task.type}\n- 状态：${task.status}\n`; const scenario = getComputingScenario(task); return `# ${task.name}\n\n- 任务编号：${task.id}\n- 领域：油气炼化\n- 计算类型：${task.type}\n- 计算软件：${task.software}\n- 状态：${task.status}\n- 输入文件：${task.inputFile}\n\n## 计算目标\n${scenario.objective}\n\n## 关键指标\n${scenario.metrics.map(metric => `- ${metric.label}：${metric.value}（${metric.note}）`).join("\n")}\n\n## 结论\n${scenario.conclusion}\n\n> 本报告由前端模拟数据生成，不代表真实生产或科研结论。\n`; }
function badge(status: ComputingStatus) { return <span className={`sc-status ${status === "运行中" ? "running" : status === "排队中" ? "queued" : status === "已完成" ? "done" : "failed"}`}><i />{status}</span>; }
function graphData(task: ComputingTask) { return Array.from({ length: 19 }, (_, i) => ({ step: i, energy: Number((-526.21 - 0.145 * (1 - Math.exp(-i / 3.1)) + Math.sin(i) * 0.001).toFixed(4)), delta: Number((43 * Math.exp(-i / 1.7)).toFixed(2)) })); }

export function ScientificComputing({ embedded = false, initialCategory }: { embedded?: boolean; initialCategory?: ComputingCategory }) {
  const { s, p, space, loaded } = useResearch();
  const params = useParams<Record<string, string | string[]>>();
  const query = useSearchParams();
  const router = useRouter();
  const contextId = valueOf(params.contextId);
  const context = contextId && contextId !== "current" ? s.spaces.find(item => item.id === contextId) : space;
  const spaceId = context?.id ?? space.id;
  const base = pathFor(spaceId, embedded);
  const taskId = valueOf(params.taskId);
  const detailCategory: ComputingCategory = taskId?.startsWith("training-") ? "training" : taskId?.startsWith("inference-") ? "inference" : "compute";
  const listBase = embedded ? `/research-spaces/${encodeURIComponent(spaceId)}/activities?tab=${detailCategory}` : base;
  const [tasks, setTasks] = useState<ComputingTask[]>([]);
  const [readySpace, setReadySpace] = useState("");
  const [category, setCategory] = useState<ComputingCategory>(() => initialCategory ?? (query.get("view") === "training" || query.get("view") === "inference" ? query.get("view") as ComputingCategory : "compute"));
  const [modelTab, setModelTab] = useState<"training" | "inference">(initialCategory === "inference" || query.get("view") === "inference" ? "inference" : "training");
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState("全部");
  const [model, setModel] = useState("全部");
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [selected, setSelected] = useState<string[]>([]);
  const [drawer, setDrawer] = useState(false);
  const [draft, setDraft] = useState<Draft>(newDraft("compute"));
  const [advanced, setAdvanced] = useState(false);
  const [errors, setErrors] = useState<string[]>([]);
  const [detailTab, setDetailTab] = useState<ComputingDetailTab>("概览");
  const [autoScroll, setAutoScroll] = useState(true);
  const [configOpen, setConfigOpen] = useState(false);

  useEffect(() => { if (!loaded || !context) return; setTasks(readTasks(context.id)); setReadySpace(context.id); }, [loaded, context?.id]);
  useEffect(() => { if (embedded && !taskId) return; if (!loaded || !contextId || contextId !== "current") return; router.replace(`${pathFor(space.id, embedded)}${taskId ? `/${encodeURIComponent(taskId)}` : ""}`); }, [embedded, loaded, contextId, router, space.id, taskId]);
  useEffect(() => { setDetailTab(normalizeComputingDetailTab(query.get("tab"))); }, [query]);
  useEffect(() => { if (!initialCategory) return; setCategory(initialCategory); if (initialCategory !== "compute") setModelTab(initialCategory); }, [initialCategory]);

  const currentCategory = category === "compute" ? "compute" : modelTab;
  const filtered = useMemo(() => filterComputingTasks(tasks, { category: currentCategory, query: search, status, model: currentCategory === "inference" ? model : "全部" }), [tasks, currentCategory, search, status, model]);
  const shown = filtered.slice((page - 1) * pageSize, page * pageSize);
  const task = tasks.find(item => item.id === taskId);
  const counts = { compute: tasks.filter(t => t.category === "compute").length, training: tasks.filter(t => t.category === "training").length, inference: tasks.filter(t => t.category === "inference").length };

  function updateTasks(next: ComputingTask[]) { setTasks(next); saveTasks(spaceId, next); }
  function changeStatus(item: ComputingTask, action: "start" | "stop" | "retry" | "complete") { const next = nextComputingStatus(item.status, action); if (!next) return; updateTasks(tasks.map(t => t.id === item.id ? { ...t, status: next, updatedAt: stamp(), progress: next === "已完成" ? 100 : next === "运行中" ? Math.max(t.progress, 12) : next === "排队中" ? 0 : t.progress, outputFile: next === "已完成" ? "计算结果.csv" : t.outputFile } : t)); notify(`任务「${item.name}」已${next === "已停止" ? "停止" : next === "排队中" ? "重新排队" : next === "已完成" ? "完成模拟运行" : "开始运行"}（本地模拟）。`); }
  function openDrawer(next: ComputingCategory) { setDraft(newDraft(next)); setErrors([]); setAdvanced(false); setDrawer(true); }
  function submit() { const found = validateComputeDraft(draft); setErrors(found); if (found.length) return; const parameters: Record<string, string> | undefined = currentCategory === "training" ? { "训练方式": draft.type, "训练轮次": draft.encut, "批大小": draft.kx, "学习率": draft.ediff, "验证集比例": `${draft.ky}%`, "目标指标": draft.precision } : currentCategory === "inference" ? { "推理模式": draft.type, "批大小": draft.kx, "置信度阈值": draft.ediff, "输出格式": draft.precision } : undefined; const next: ComputingTask = { id: `${currentCategory}-${Date.now()}`, spaceId, category: currentCategory, name: draft.name.trim(), type: draft.type, software: draft.software, inputFile: draft.fileName, owner: p.name, updatedAt: stamp(), status: "排队中", progress: 0, model: currentCategory === "compute" ? undefined : draft.model, precision: draft.precision, resource: draft.resource, note: draft.note, duration: "0 分钟", parameters, ...(currentCategory === "compute" ? { domain: "油气炼化" as const, templateId: draft.templateId } : {}) }; updateTasks([next, ...tasks]); setDrawer(false); setSearch(""); setStatus("全部"); setPage(1); notify(`任务「${next.name}」已提交至本地模拟队列。`); router.push(`${base}/${next.id}`); }
  function downloadResult(item: ComputingTask, name = item.category === "training" ? "训练指标.csv" : item.category === "inference" ? "推理结果.csv" : "炼化计算结果.csv") { const scenario = item.category === "compute" ? getComputingScenario(item) : null; const csv = scenario ? `${scenario.tableHeaders.join(",")}\n${scenario.tableRows.map(row => row.join(",")).join("\n")}\n` : item.category === "training" ? `指标,数值\n模型,${item.model ?? "未指定"}\n训练进度,${item.progress}%\n当前指标,${item.metric ?? "示例"}\n` : `样本,预测值,置信度\n样本-001,0.862,0.91\n样本-002,0.784,0.87\n`; const content = name.endsWith(".csv") || name.endsWith(".xlsx") ? csv : scenario ? `[油气炼化模拟任务] ${item.name}\n文件：${name}\n任务状态：${item.status}\n计算类型：${item.type}\n计算软件：${item.software}\n工作目录：${scenario.workdir}\n\n${scenario.conclusion}\n` : `[本地模拟结果] ${item.name}\n文件：${name}\n任务状态：${item.status}\n`; downloadFile(name, content, name.endsWith(".csv") ? "text/csv;charset=utf-8" : "text/plain;charset=utf-8"); notify("已下载示例结果文件。"); }
  function selectCategory(next: ComputingCategory) { router.replace(`${base}?view=${next}`); setCategory(next); setModelTab(next === "inference" ? "inference" : "training"); setStatus("全部"); setSearch(""); setPage(1); setSelected([]); }

  if (!loaded || readySpace !== spaceId) return <div className="sc-page" role="status">正在加载科学计算…</div>;
  if (!context || !canEnter(s, p, context.id)) return <div className="sc-page"><h1>无法访问此科研空间</h1></div>;
  if (taskId && !task) return <div className="sc-page"><Link href={listBase}>返回任务列表</Link><h1>任务不存在</h1></div>;

  return <div className={`sc-page sc-${currentCategory}${embedded ? " sc-embedded" : ""}`}>
    {task ? <>
      {!embedded && <div className="sc-breadcrumb">科研空间 <span>/</span> {context.name} <span>/</span> <Link href={base}>科学计算</Link> <span>/</span> {task.name}</div>}
      <header className="sc-detail-head"><div className="sc-title-group"><span className="sc-title-icon"><Box size={27}/></span><div><div className="sc-title-row"><h1>{task.name}</h1>{badge(task.status)}<span className="sc-demo">模拟数据</span></div><p>任务ID：{task.id}　 |　负责人：{task.owner}　 |　开始时间：{task.updatedAt}　 |　计算软件：{task.software || "PyTorch"}</p></div></div><div className="sc-head-actions">{task.status === "运行中" && <button className="sc-btn primary" onClick={() => changeStatus(task, "complete")}><CheckCircle2 size={14}/>完成模拟运行</button>}{task.status === "运行中" && <button className="sc-btn danger" onClick={() => changeStatus(task, "stop")}><Square size={14}/>停止任务</button>}{task.status === "排队中" && <button className="sc-btn primary" onClick={() => changeStatus(task, "start")}><Play size={14}/>开始模拟运行</button>}{task.status === "已完成" && <button className="sc-btn" onClick={() => { downloadFile(`${task.name}-计算报告.md`, taskReport(task), "text/markdown;charset=utf-8"); notify("已生成示例计算报告。"); }}><FileText size={15}/>生成报告</button>}{task.status === "已完成" && <button className="sc-btn" onClick={() => downloadResult(task)}><Download size={15}/>下载结果</button>}{["失败", "已停止"].includes(task.status) && <button className="sc-btn primary" onClick={() => changeStatus(task, "retry")}>重试</button>}<button className="sc-btn" onClick={() => setConfigOpen(true)}><Settings2 size={15}/>查看配置</button><Link className="sc-btn" href={listBase}><ArrowLeft size={15}/>返回任务列表</Link></div></header>
      <nav className="sc-detail-tabs" aria-label="任务详情" role="tablist">{COMPUTING_DETAIL_TABS.map(tab => <button key={tab} role="tab" aria-selected={detailTab === tab} className={detailTab === tab ? "active" : ""} onClick={() => { setDetailTab(tab); router.replace(`${base}/${task.id}?tab=${encodeURIComponent(tab)}`); }}>{tab}</button>)}</nav>
      <TaskDetail task={task} tab={detailTab} autoScroll={autoScroll} setAutoScroll={setAutoScroll} downloadResult={downloadResult}/>
    </> : <>
      {!embedded && <div className="sc-breadcrumb">科研空间 <span>/</span> {context.name} <span>/</span> 科学计算</div>}
      {!embedded && <header className="sc-list-head"><div><h1>科研任务</h1><p>管理和执行与本课题相关的各类科研任务，支持计算任务、模型任务等多种类型。</p></div><div className="sc-head-actions"><Link className="sc-btn" href={`/research-spaces/${encodeURIComponent(spaceId)}/tasks`}>进入会话</Link><Link className="sc-btn primary" href="/workspace">发起科研任务</Link></div></header>}
      {!embedded && <nav className="sc-primary-tabs" aria-label="任务类型"><button className={category === "compute" ? "active" : ""} onClick={() => selectCategory("compute")}>计算任务</button><button className={category !== "compute" ? "active" : ""} onClick={() => selectCategory("training")}>模型任务</button></nav>}
      {category !== "compute" && !embedded && <nav className="sc-secondary-tabs" aria-label="模型任务类型"><button className={modelTab === "training" ? "active" : ""} onClick={() => { router.replace(`${base}?view=training`); setModelTab("training"); setPage(1); setSelected([]); }}>模型训练</button><button className={modelTab === "inference" ? "active" : ""} onClick={() => { router.replace(`${base}?view=inference`); setModelTab("inference"); setPage(1); setSelected([]); }}>模型推理</button></nav>}
      <section className="sc-table-card"><div className="sc-toolbar"><div className="sc-toolbar-title"><h2>{currentCategory === "compute" ? "计算任务列表" : currentCategory === "training" ? "模型训练任务列表" : "模型推理任务列表"}</h2><p>{currentCategory === "compute" ? "人工发起并管理计算任务，与会话任务相互独立" : currentCategory === "training" ? "人工发起的模型训练任务，与对话中的模型训练相互独立" : "手动发起的模型推理任务，适用于批量数据预测与分析。"}</p></div><div className="sc-filters"><label className="sc-search"><Search size={15}/><input aria-label="搜索任务" placeholder={currentCategory === "inference" ? "搜索任务名称、输入数据或负责人…" : "搜索任务名称、软件或负责人…"} value={search} onChange={e => { setSearch(e.target.value); setPage(1); }}/></label><label className="sc-filter-label">{"运行状态"}<select aria-label="筛选任务状态" value={status} onChange={e => { setStatus(e.target.value); setPage(1); }}>{statusOptions.map(option => <option key={option}>{option}</option>)}</select></label>{currentCategory === "inference" && <label className="sc-filter-label">模型<select aria-label="筛选模型" value={model} onChange={e => { setModel(e.target.value); setPage(1); }}><option>全部</option>{models.map(name => <option key={name}>{name}</option>)}</select></label>}<button className="sc-btn primary" onClick={() => openDrawer(currentCategory)}><Plus size={16}/>{currentCategory === "compute" ? "发起计算任务" : currentCategory === "training" ? "发起训练任务" : "发起推理任务"}</button></div></div>
      {selected.length > 0 && <div className="sc-selection">已选择 {selected.length} 项 <button onClick={() => setSelected([])}>取消选择</button></div>}
      <div className="sc-table-scroll"><table className="sc-table"><thead><tr><th><input type="checkbox" aria-label="选择当前页任务" checked={shown.length > 0 && shown.every(t => selected.includes(t.id))} onChange={e => setSelected(e.target.checked ? [...new Set([...selected, ...shown.map(t => t.id)])] : selected.filter(id => !shown.some(t => t.id === id)))}/></th><th>任务名称</th><th>{currentCategory === "compute" ? "计算类型" : "关联模型 / 版本"}</th><th>{currentCategory === "compute" ? "所属软件 / 工具" : currentCategory === "training" ? "训练数据集" : "输入数据"}</th><th>负责人</th><th>更新时间 ↓</th><th>{currentCategory === "training" ? "训练状态" : "运行状态"}</th>{currentCategory === "training" && <th>训练进度</th>}{currentCategory === "inference" && <th>输出概览</th>}<th>操作</th></tr></thead><tbody>{shown.map(row => <tr key={row.id}><td><input type="checkbox" aria-label={`选择 ${row.name}`} checked={selected.includes(row.id)} onChange={e => setSelected(e.target.checked ? [...selected, row.id] : selected.filter(id => id !== row.id))}/></td><td className="sc-name"><Link href={`${base}/${row.id}`}>{row.name}</Link></td><td>{currentCategory === "compute" ? row.type : row.model}</td><td>{currentCategory === "compute" ? row.software : row.inputFile}</td><td>{row.owner}</td><td>{row.updatedAt}</td><td>{badge(row.status)}</td>{currentCategory === "training" && <td><span className="sc-progress-cell"><i><b style={{ width: `${row.progress}%` }}/></i>{row.progress ? `${row.progress}%` : "—"}</span></td>}{currentCategory === "inference" && <td className="sc-output">预测样本数：{row.samples?.toLocaleString() ?? "—"}<small>{row.metric}</small></td>}<td><div className="sc-row-actions"><Link href={`${base}/${row.id}`}>查看详情</Link>{row.status === "运行中" && <button onClick={() => changeStatus(row, "stop")}>停止任务</button>}{row.status === "排队中" && <button onClick={() => changeStatus(row, "start")}>开始运行</button>}{row.status === "已完成" && <button onClick={() => downloadResult(row, row.outputFile ?? "计算结果.csv")}>下载结果</button>}{["失败", "已停止"].includes(row.status) && <button onClick={() => changeStatus(row, "retry")}>重试</button>}<button className="sc-icon" aria-label={`${row.name} 的更多操作`} onClick={() => notify(`任务编号：${row.id}；状态：${row.status}。`)}><MoreHorizontal size={16}/></button></div></td></tr>)}</tbody></table>{shown.length === 0 && <div className="sc-empty">没有符合条件的任务。调整筛选条件或发起新任务。</div>}</div>
      <footer className="sc-table-footer"><span>共 {filtered.length} 条记录 · {currentCategory === "compute" ? counts.compute : currentCategory === "training" ? counts.training : counts.inference} 条当前类型任务</span><div><button disabled={page <= 1} onClick={() => setPage(page - 1)} aria-label="上一页"><ChevronLeft size={16}/></button><span className="sc-current-page">{page}</span><button disabled={page * pageSize >= filtered.length} onClick={() => setPage(page + 1)} aria-label="下一页"><ChevronRight size={16}/></button><select aria-label="每页记录数" value={pageSize} onChange={e => { setPageSize(Number(e.target.value)); setPage(1); }}><option value="10">10 条/页</option><option value="20">20 条/页</option><option value="50">50 条/页</option></select></div></footer></section>
      {!embedded && <OverviewCards category={currentCategory} tasks={tasks} />}
    </>}
    {configOpen && task && <div className="sc-overlay" onMouseDown={e => { if (e.target === e.currentTarget) setConfigOpen(false); }}><section className="sc-config-dialog" role="dialog" aria-modal="true" aria-label="任务配置" onKeyDown={e => { if (e.key === "Escape") setConfigOpen(false); }}><header><h2>任务配置</h2><button onClick={() => setConfigOpen(false)} aria-label="关闭配置"><X size={18}/></button></header><dl>{([["任务名称",task.name],["计算类型",task.type],["计算软件",task.software || "PyTorch"],["输入文件",task.inputFile],["领域",task.domain || "模型计算"],["算力资源",task.resource || "AI4S-HPC"]] as string[][]).concat(task.category === "compute" ? getComputingScenario(task).parameters.map(item => [item.label, item.value]) : []).map(([label,value]) => <div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl></section></div>}
    {drawer && currentCategory !== "compute" && <ModelTaskDrawer category={currentCategory} draft={draft} setDraft={setDraft} errors={errors} onClose={() => setDrawer(false)} onSubmit={submit} />}
    {drawer && currentCategory === "compute" && <div className="sc-overlay" onMouseDown={e => { if (e.target === e.currentTarget) setDrawer(false); }}><aside className="sc-drawer" role="dialog" aria-modal="true" aria-labelledby="sc-drawer-title" onKeyDown={e => { if (e.key === "Escape") setDrawer(false); }}><div className="sc-drawer-head"><div><h2 id="sc-drawer-title">{currentCategory === "compute" ? "发起计算任务" : currentCategory === "training" ? "发起训练任务" : "发起推理任务"}</h2><p>配置输入、领域参数、计算软件与运行资源</p></div><button aria-label="关闭" onClick={() => setDrawer(false)}><X size={20}/></button></div><div className="sc-drawer-body"><section><h3>基本信息 <ChevronDown size={14}/></h3><label>任务名称 <em>*</em><input maxLength={100} value={draft.name} onChange={e => setDraft({ ...draft, name: e.target.value })} autoFocus placeholder="例如：常减压装置原油切割方案模拟"/><small>{draft.name.length}/100</small></label><label>计算模板 <em>*</em><div className="sc-type-options">{(currentCategory === "compute" ? ["稳态流程模拟", "炼化反应器模拟", "燃烧与传热CFD"] : currentCategory === "training" ? ["模型训练", "增量训练", "超参数优化"] : ["批量预测", "单样本预测", "模型评估"]).map(type => <button type="button" key={type} className={draft.type === type ? "selected" : ""} onClick={() => setDraft({ ...draft, type, ...(currentCategory === "compute" ? computeTemplate(type) : {}) })}>{type}</button>)}</div></label>{currentCategory === "compute" ? <label>计算软件/工具 <em>*</em><input value={draft.software} readOnly/></label> : <label>关联模型 <em>*</em><select value={draft.model} onChange={e => setDraft({ ...draft, model: e.target.value })}>{models.map(name => <option key={name}>{name}</option>)}</select></label>}</section><section><h3>输入数据 <ChevronDown size={14}/></h3><label>{draft.type === "燃烧与传热CFD" ? "几何/网格文件" : draft.type === "炼化反应器模拟" ? "原料性质与动力学数据" : "原油评价或流程数据"} <em>*</em><span className="sc-upload"><Upload size={18}/><span>点击上传或拖拽文件到此处<small>支持 XLSX、CSV、JSON、BKP、STEP、MSH 格式</small></span><input aria-label="上传炼化计算输入文件" type="file" accept=".xlsx,.csv,.json,.bkp,.hsc,.step,.msh,.foam" onChange={e => setDraft({ ...draft, fileName: e.target.files?.[0]?.name ?? "" })}/></span>{draft.fileName && <small>已选择：{draft.fileName}</small>}</label><button className="sc-btn" onClick={() => { const fileName = draft.type === "燃烧与传热CFD" ? "heater_furnace_v12.step" : draft.type === "炼化反应器模拟" ? "reactor_feed_properties.xlsx" : "crude_assay_2026Q3.xlsx"; setDraft({ ...draft, fileName }); notify("已选择炼化领域示例输入文件。"); }}>从文件库选择示例</button></section><section><h3>领域计算参数 <button onClick={() => setDraft({ ...draft, encut: "120", kx: "365", ky: "145", kz: "3.8", ediff: "0.5" })}>使用推荐参数</button></h3><div className="sc-form-grid">{draft.type === "燃烧与传热CFD" ? <><label>燃料气流量 (Nm³/h)<input value={draft.encut} onChange={e => setDraft({ ...draft, encut: e.target.value })}/></label><label>空气过剩系数<input value={draft.ediff} onChange={e => setDraft({ ...draft, ediff: e.target.value })}/></label><label>湍流模型<select><option>Realizable k-ε</option><option>SST k-ω</option></select></label><label>辐射模型<select><option>P1</option><option>DO</option></select></label></> : draft.type === "炼化反应器模拟" ? <><label>反应温度 (℃)<input value={draft.kx} onChange={e => setDraft({ ...draft, kx: e.target.value })}/></label><label>反应压力 (MPa)<input value={draft.ediff} onChange={e => setDraft({ ...draft, ediff: e.target.value })}/></label><label>原料流量 (t/h)<input value={draft.encut} onChange={e => setDraft({ ...draft, encut: e.target.value })}/></label><label>求解模式<select><option>严格动力学</option><option>稳态标定</option></select></label></> : <><label>处理量 (t/h)<input value={draft.encut} onChange={e => setDraft({ ...draft, encut: e.target.value })}/></label><label>进料温度 (℃)<input value={draft.kx} onChange={e => setDraft({ ...draft, kx: e.target.value })}/></label><label>操作压力 (kPa)<input value={draft.ky} onChange={e => setDraft({ ...draft, ky: e.target.value })}/></label><label>物性方法<select><option>Peng-Robinson</option><option>SRK</option></select></label></>}</div><button className="sc-expand" onClick={() => setAdvanced(!advanced)}>高级参数 <ChevronDown size={14}/></button>{advanced && <div className="sc-form-grid"><label>最大迭代次数<input defaultValue="200"/></label><label>收敛容差<input defaultValue="1e-5"/></label><label>初始化方式<select><option>自动初始化</option><option>读取检查点</option></select></label><label>结果采样间隔<input defaultValue="10"/></label></div>}</section><section><h3>算力资源与运行环境 <ChevronDown size={14}/></h3><div className="sc-form-grid"><label>算力资源 <em>*</em><input value={draft.resource} readOnly/></label><label>并行任务数<select value={draft.parallel} onChange={e => setDraft({ ...draft, parallel: e.target.value })}><option>1</option><option>2</option><option>4</option></select></label><label>运行时间上限（小时）<input type="number" min="1" value={draft.hours} onChange={e => setDraft({ ...draft, hours: e.target.value })}/></label><label>运行模式<input value={draft.precision} readOnly/></label></div><div className="sc-resource-estimate"><Info size={14}/>提交后将保存输入、领域参数、软件版本和资源配置快照。</div></section><section><h3>输出位置 <ChevronDown size={14}/></h3><label>输出目录 <em>*</em><input value={draft.output} onChange={e => setDraft({ ...draft, output: e.target.value })}/></label><div className="sc-form-grid"><label>优先级<select value={draft.priority} onChange={e => setDraft({ ...draft, priority: e.target.value })}><option>普通</option><option>高</option></select></label><label>备注<input maxLength={200} value={draft.note} onChange={e => setDraft({ ...draft, note: e.target.value })} placeholder="请输入工况、数据来源或评价目的"/></label></div></section>{errors.length > 0 && <div className="sc-errors" role="alert">{errors.join("；")}</div>}</div><div className="sc-drawer-foot"><button className="sc-btn" onClick={() => setDrawer(false)}>取消</button><button className="sc-btn primary" onClick={submit}>提交运行</button></div></aside></div>}
  </div>;
}

function ModelTaskDrawer({ category, draft, setDraft, errors, onClose, onSubmit }: { category: "training" | "inference"; draft: Draft; setDraft: (draft: Draft) => void; errors: string[]; onClose: () => void; onSubmit: () => void }) {
  const training = category === "training";
  return <div className="sc-overlay" onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }}><aside className="sc-drawer" role="dialog" aria-modal="true" aria-labelledby="sc-model-drawer-title" onKeyDown={event => { if (event.key === "Escape") onClose(); }}><div className="sc-drawer-head"><div><h2 id="sc-model-drawer-title">{training ? "发起训练任务" : "发起推理任务"}</h2><p>{training ? "配置模型、训练数据、超参数与评价指标" : "配置模型版本、输入数据、推理参数与输出结果"}</p></div><button aria-label="关闭" onClick={onClose}><X size={20}/></button></div><div className="sc-drawer-body"><section><h3>基本信息 <ChevronDown size={14}/></h3><label>任务名称 <em>*</em><input maxLength={100} value={draft.name} onChange={event => setDraft({ ...draft, name: event.target.value })} autoFocus placeholder={training ? "例如：催化活性预测模型训练" : "例如：催化剂候选配方批量预测"}/><small>{draft.name.length}/100</small></label><label>{training ? "训练方式" : "推理模式"} <em>*</em><div className="sc-type-options">{(training ? ["全量训练", "增量训练", "超参数优化"] : ["批量预测", "单样本预测", "模型评估"]).map(type => <button type="button" key={type} className={draft.type === type ? "selected" : ""} onClick={() => setDraft({ ...draft, type })}>{type}</button>)}</div></label><label>关联模型 <em>*</em><select value={draft.model} onChange={event => setDraft({ ...draft, model: event.target.value })}>{models.map(name => <option key={name}>{name}</option>)}</select></label></section><section><h3>{training ? "训练数据" : "推理输入"} <ChevronDown size={14}/></h3><label>{training ? "训练数据集文件" : "待预测数据文件"} <em>*</em><span className="sc-upload"><Upload size={18}/><span>点击上传或拖拽文件到此处<small>支持 CSV、XLSX、JSON、Parquet 格式</small></span><input aria-label={training ? "上传训练数据集" : "上传推理输入数据"} type="file" accept=".csv,.xlsx,.json,.parquet" onChange={event => setDraft({ ...draft, fileName: event.target.files?.[0]?.name ?? "" })}/></span>{draft.fileName && <small>已选择：{draft.fileName}</small>}</label><button className="sc-btn" onClick={() => { setDraft({ ...draft, fileName: training ? "refinery_training_dataset_v3.csv" : "candidate_samples_2026Q4.csv" }); notify("已选择模型任务示例数据。"); }}>从文件库选择示例</button></section><section><h3>{training ? "训练参数" : "推理参数"}</h3><div className="sc-form-grid">{training ? <><label>训练轮次<input type="number" min="1" value={draft.encut} onChange={event => setDraft({ ...draft, encut: event.target.value })}/></label><label>批大小<input type="number" min="1" value={draft.kx} onChange={event => setDraft({ ...draft, kx: event.target.value })}/></label><label>学习率<input value={draft.ediff} onChange={event => setDraft({ ...draft, ediff: event.target.value })}/></label><label>验证集比例（%）<input type="number" min="1" max="50" value={draft.ky} onChange={event => setDraft({ ...draft, ky: event.target.value })}/></label><label>目标指标<select value={draft.precision} onChange={event => setDraft({ ...draft, precision: event.target.value })}><option>Validation Loss</option><option>Accuracy</option><option>R²</option><option>MAE</option></select></label></> : <><label>批大小<input type="number" min="1" value={draft.kx} onChange={event => setDraft({ ...draft, kx: event.target.value })}/></label><label>置信度阈值<input type="number" min="0" max="1" step="0.05" value={draft.ediff} onChange={event => setDraft({ ...draft, ediff: event.target.value })}/></label><label>输出格式<select value={draft.precision} onChange={event => setDraft({ ...draft, precision: event.target.value })}><option>CSV + JSON</option><option>CSV</option><option>JSON</option></select></label><label>低置信结果<select><option>标记并保留</option><option>单独输出</option><option>过滤</option></select></label></>}</div></section><section><h3>算力资源与输出 <ChevronDown size={14}/></h3><div className="sc-form-grid"><label>算力资源<select value={draft.resource} onChange={event => setDraft({ ...draft, resource: event.target.value })}><option>GPU 节点（A100 80GB）</option><option>GPU 节点（V100 32GB）</option><option>CPU 节点（64核）</option></select></label><label>运行时间上限（小时）<input type="number" min="1" value={draft.hours} onChange={event => setDraft({ ...draft, hours: event.target.value })}/></label></div><label>输出目录<input value={draft.output} onChange={event => setDraft({ ...draft, output: event.target.value })}/></label><label>备注<input maxLength={200} value={draft.note} onChange={event => setDraft({ ...draft, note: event.target.value })} placeholder="填写数据版本、训练目标或推理用途"/></label></section>{errors.length > 0 && <div className="sc-errors" role="alert">{errors.join("；")}</div>}</div><div className="sc-drawer-foot"><button className="sc-btn" onClick={onClose}>取消</button><button className="sc-btn primary" onClick={onSubmit}>提交任务</button></div></aside></div>;
}

function OverviewCards({ category, tasks }: { category: ComputingCategory; tasks: ComputingTask[] }) {
  const relevant = tasks.filter(t => t.category === category);
  return <div className="sc-overview-grid"><section className="sc-card"><h3><ChartNoAxesCombined size={18}/>{category === "inference" ? "推理结果统计" : category === "training" ? "训练资源概览" : "资源概览"}<small>集群：AI4S-HPC | 更新时间：2024-10-28 14:32</small><button onClick={() => notify("当前展示本地模拟资源概览。")}>查看完整统计 <ChevronRight size={13}/></button></h3><div className="sc-metrics">{(category === "inference" ? [["总推理任务", String(relevant.length), "125,680", "总预测样本数"], ["已完成", String(relevant.filter(t => t.status === "已完成").length), "42", "生成结果文件"]] : [["CPU", "62%", "已用 496 核 / 总 800 核", "cpu"], ["GPU", "78%", "已用 62 张 / 总 80 张", "gpu"], ["内存", "54%", "已用 1.1 TB / 总 2.0 TB", "memory"]]).map(([label, value, sub]) => <div className="sc-metric" key={label}><div className="sc-metric-icon"><Cpu size={23}/></div><strong>{label}</strong><b>{value}</b>{value.includes("%") && <span className="sc-meter"><i style={{width:value}}/></span>}<small>{sub}</small></div>)}</div></section><section className="sc-card"><h3><FileText size={18}/>{category === "inference" ? "最近推理日志" : category === "training" ? "最近训练事件" : "最近运行日志"}<button onClick={() => notify("日志为本地模拟数据。")}>查看全部 <ChevronRight size={13}/></button></h3><div className="sc-events">{relevant.slice(0, 5).map(row => <div key={row.id}><time>{row.updatedAt.slice(5)}</time><i className={row.status === "已完成" ? "done" : row.status === "失败" ? "failed" : "running"}/><span>任务「{row.name}」{row.status === "已完成" ? "已完成，结果文件已生成" : row.status === "失败" ? "执行失败，请检查输入文件" : `当前${row.status}`}</span></div>)}</div></section></div>;
}

function ModelTaskDetail({ task, tab, downloadResult }: { task: ComputingTask; tab: ComputingDetailTab; downloadResult: (task: ComputingTask, name?: string) => void }) {
  const scenario = getModelTaskScenario(task);
  const training = task.category === "training";
  const failed = task.status === "失败";
  const metricCards = <div className="sc-stat-grid">{scenario.metrics.map((metric, index) => <div className="sc-stat" key={metric.label}>{failed && index === 0 ? <CircleHelp size={22}/> : <Cpu size={22}/>}<span>{metric.label}</span><strong>{metric.value}</strong><small>{metric.note}</small></div>)}</div>;
  const stages = <section className="sc-card sc-run-stages"><h3><Activity size={18}/>{training ? "训练阶段" : "推理阶段"}</h3><div className="sc-stage-list">{scenario.stages.map((stage, index) => <div key={stage.name} className={`sc-stage-item ${stage.status === "失败" ? "failed" : stage.status === "运行中" ? "running" : stage.status === "已完成" ? "done" : "queued"}`}><span>{index + 1}</span><div><strong>{stage.name}</strong><small>{stage.detail}</small></div><b>{stage.status}</b></div>)}</div></section>;
  const config = <section className="sc-card sc-summary"><h3><Settings2 size={18}/>{training ? "训练配置快照" : "推理配置快照"}</h3><dl><div><dt>关联模型</dt><dd>{task.model ?? "—"}</dd></div><div><dt>输入数据</dt><dd>{task.inputFile}</dd></div>{Object.entries(task.parameters ?? {}).map(([label, value]) => <div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}<div><dt>运行资源</dt><dd>{task.resource ?? "GPU 节点（A100 80GB）"}</dd></div></dl></section>;
  const chart = <section className="sc-card sc-chart"><h3><Activity size={18}/>{scenario.chartTitle}</h3><ResponsiveContainer width="100%" height={300}><LineChart data={scenario.chartData}><CartesianGrid stroke="#e5edf8"/><XAxis dataKey="step" tick={{fontSize:11}}/><YAxis tick={{fontSize:11}}/><Tooltip/><Line type="monotone" dataKey="value" stroke={failed ? "#e24652" : "#0969f6"} strokeWidth={2} dot={{r:3}} isAnimationActive={false}/></LineChart></ResponsiveContainer></section>;
  const resultTable = <section className="sc-card sc-scan"><h3><FileText size={18}/>{scenario.tableTitle}</h3><div className="sc-table-scroll"><table className="sc-table"><thead><tr>{scenario.tableHeaders.map(header => <th key={header}>{header}</th>)}</tr></thead><tbody>{scenario.tableRows.map((row, index) => <tr key={index}>{row.map((cell, cellIndex) => <td key={`${index}-${cellIndex}`}>{cell}</td>)}</tr>)}</tbody></table></div></section>;
  const files = <section className="sc-card sc-files"><h3><FileText size={18}/>结果文件</h3><table className="sc-table"><thead><tr><th>文件名</th><th>说明</th><th>操作</th></tr></thead><tbody>{scenario.files.map(file => <tr key={file.name}><td>{file.name}</td><td>{file.description}</td><td><button className="sc-link" onClick={() => downloadResult(task, file.name)}>下载</button></td></tr>)}</tbody></table></section>;
  const log = <section className="sc-card sc-log"><h3><FileText size={18}/>完整运行日志</h3><pre>{scenario.log}</pre></section>;
  if (tab === "配置与运行") return <>{metricCards}<div className="sc-detail-grid"><div>{stages}</div><div>{config}</div></div></>;
  if (tab === "结果分析") return <div className="sc-detail-grid"><div>{chart}{resultTable}</div><div><section className={`sc-card sc-domain-conclusion${failed ? " failed" : ""}`}><h3><Target size={18}/>{failed ? "异常说明" : training ? "训练评价" : "推理摘要"}</h3><p>{scenario.objective}</p></section></div></div>;
  if (tab === "文件与日志") return <div className="sc-result-only">{files}{log}</div>;
  return <>{metricCards}<div className="sc-overview-detail"><section className="sc-card sc-overview-primary"><h3><Activity size={18}/>任务状态与目标</h3><strong>{failed ? `${training ? "训练" : "推理"}任务异常终止` : task.status === "已完成" ? `${training ? "训练" : "推理"}任务已完成` : `${training ? "训练" : "推理"}任务正在执行`}</strong><p>{scenario.objective}</p></section><section className="sc-card sc-overview-links"><h3><Target size={18}/>查看完整信息</h3><Link href="?tab=配置与运行">配置快照与运行阶段 <ChevronRight size={14}/></Link><Link href="?tab=结果分析">指标曲线与结果分析 <ChevronRight size={14}/></Link><Link href="?tab=文件与日志">结果文件与完整日志 <ChevronRight size={14}/></Link></section></div></>;
}

function LegacyModelTaskDetail({ task, tab, downloadResult }: { task: ComputingTask; tab: ComputingDetailTab; downloadResult: (task: ComputingTask, name?: string) => void }) {
  const training = task.category === "training";
  const curve = Array.from({ length: 13 }, (_, i) => ({ step: i * 10, value: training ? Number((1.24 * Math.exp(-i / 3.7) + 0.12).toFixed(3)) : Number((0.64 + 0.23 * (1 - Math.exp(-i / 3.5))).toFixed(3)) }));
  const resultName = training ? "训练指标.csv" : "推理结果.csv";
  if (tab === "文件与日志") return <div className="sc-result-only"><section className="sc-card sc-model-card"><h3><FileText size={18}/>结果文件</h3>{task.status === "已完成" ? <table className="sc-table"><thead><tr><th>文件名</th><th>说明</th><th>操作</th></tr></thead><tbody><tr><td>{resultName}</td><td>{training ? "训练曲线与评价指标" : "预测结果与置信度"}</td><td><button className="sc-link" onClick={() => downloadResult(task,resultName)}>下载</button></td></tr></tbody></table> : <p>任务完成后将在此生成结果文件。</p>}</section><section className="sc-card sc-log sc-model-card"><h3><FileText size={18}/>运行日志</h3><pre>{`[本地模拟日志] ${task.name}\n模型：${task.model ?? "待选择"}\n输入：${task.inputFile}\n当前状态：${task.status}\n完成进度：${task.progress}%\n${task.status === "已完成" ? "任务已完成，示例结果已生成。" : "等待本地模拟任务推进。"}`}</pre></section></div>;
  return <><div className="sc-stat-grid"><div className="sc-stat"><Box size={22}/><span>任务类型</span><strong>{training ? "模型训练" : "模型推理"}</strong><small>独立于科研会话</small></div><div className="sc-stat"><Cpu size={22}/><span>当前进度</span><strong>{task.progress}%</strong><small>{task.status}</small></div><div className="sc-stat"><Activity size={22}/><span>{training ? "当前指标" : "预测样本"}</span><strong>{training ? task.metric ?? "—" : task.samples?.toLocaleString() ?? "—"}</strong><small>本地模拟数据</small></div><div className="sc-stat"><FileText size={22}/><span>结果文件</span><strong>{task.status === "已完成" ? "1 个" : "待生成"}</strong><small>{resultName}</small></div></div><div className="sc-detail-grid"><div><section className="sc-card sc-model-card"><h3><Activity size={18}/>{training ? "训练指标变化" : "推理置信度趋势"}</h3><ResponsiveContainer width="100%" height={310}><LineChart data={curve} margin={{top:8,right:18,bottom:10,left:0}}><CartesianGrid stroke="#e5edf8"/><XAxis dataKey="step" tick={{fontSize:11}}/><YAxis tick={{fontSize:11}}/><Tooltip/><Line dataKey="value" stroke="#0969f6" strokeWidth={2} dot={{r:2}} isAnimationActive={false}/></LineChart></ResponsiveContainer><p>图表为前端示例曲线，接入计算服务后展示真实指标。</p></section></div><div><section className="sc-card sc-summary"><h3><Settings2 size={18}/>任务配置</h3><dl><div><dt>关联模型</dt><dd>{task.model ?? "—"}</dd></div><div><dt>输入数据</dt><dd>{task.inputFile}</dd></div><div><dt>负责人</dt><dd>{task.owner}</dd></div><div><dt>运行资源</dt><dd>{task.resource ?? "AI4S-HPC"}</dd></div><div><dt>更新时间</dt><dd>{task.updatedAt}</dd></div><div><dt>任务状态</dt><dd>{task.status}</dd></div></dl></section><section className="sc-card sc-log"><h3><FileText size={18}/>最近运行日志</h3><pre>{`[本地模拟日志]\n${task.name}\n状态：${task.status}\n进度：${task.progress}%\n${task.status === "已完成" ? "示例结果已生成。" : "等待后续模拟执行。"}`}</pre></section></div></div></>;
}

function RefineryTaskDetail({ task, tab, autoScroll, setAutoScroll, downloadResult }: { task: ComputingTask; tab: ComputingDetailTab; autoScroll: boolean; setAutoScroll: (value: boolean) => void; downloadResult: (task: ComputingTask, name?: string) => void }) {
  const scenario = getComputingScenario(task);
  const complete = task.status === "已完成";
  const invalid = task.status === "失败";
  const metrics = scenario.metrics.map((metric, index) => index === 0 && !complete ? { ...metric, value: invalid ? metric.value : `${task.progress}%` } : metric);
  const metricCards = <div className="sc-stat-grid">{metrics.map((metric, index) => <div className="sc-stat" key={metric.label}>{invalid && index === 0 ? <CircleHelp size={22}/> : complete ? <CheckCircle2 size={22}/> : <Cpu size={22}/>}<span>{metric.label}</span><strong>{metric.value}</strong><small>{metric.note}</small>{index === 0 && !complete && !invalid && <i className="sc-meter"><b style={{width:`${task.progress}%`}}/></i>}</div>)}</div>;
  const parameterCard = <section className="sc-card sc-config"><h3><Settings2 size={18}/>计算配置快照</h3><dl>{scenario.parameters.map(parameter => <div key={parameter.label}><dt>{parameter.label}</dt><dd>{parameter.value}</dd></div>)}</dl></section>;
  const stageCard = <section className="sc-card sc-run-stages"><h3><Activity size={18}/>计算阶段</h3><div className="sc-stage-list">{scenario.stages.map((stage, index) => <div key={stage.name} className={`sc-stage-item ${stage.status === "失败" ? "failed" : stage.status === "运行中" ? "running" : stage.status === "已完成" ? "done" : "queued"}`}><span>{index + 1}</span><div><strong>{stage.name}</strong><small>{stage.detail}</small></div><b>{stage.status}</b></div>)}</div></section>;
  const summary = <section className="sc-card sc-summary"><h3><FileText size={18}/>任务与运行环境</h3><dl>{[["计算类型", task.type], ["计算软件", task.software], ["输入文件", task.inputFile], ["工作目录", scenario.workdir], ["负责人", task.owner], ["运行资源", task.resource ?? "炼化科学计算节点"]].map(([label, value]) => <div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl></section>;
  const dataTable = <section className="sc-card sc-scan"><h3><FileText size={18}/>{scenario.tableTitle}</h3><div className="sc-table-scroll"><table className="sc-table"><thead><tr>{scenario.tableHeaders.map(header => <th key={header}>{header}</th>)}</tr></thead><tbody>{scenario.tableRows.map((row, index) => <tr key={index}>{row.map((cell, cellIndex) => <td key={`${index}-${cellIndex}`}>{cell}</td>)}</tr>)}</tbody></table></div></section>;
  const resultChart = <section className="sc-card sc-chart"><h3><Activity size={18}/>{scenario.chartTitle}<small>单位：{scenario.chartUnit}</small></h3><ResponsiveContainer width="100%" height={290}><LineChart data={scenario.chartData} margin={{top:10,right:18,left:6,bottom:8}}><CartesianGrid stroke="#e5edf8"/><XAxis dataKey="step" tick={{fontSize:11}}/><YAxis tick={{fontSize:11}}/><Tooltip formatter={(value) => [`${value} ${scenario.chartUnit}`, scenario.chartTitle]}/><Line type="monotone" dataKey="value" stroke={invalid ? "#e24652" : "#0969f6"} strokeWidth={2} dot={{r:3}} isAnimationActive={false}/></LineChart></ResponsiveContainer></section>;
  const conclusion = <section className={`sc-card sc-domain-conclusion${invalid ? " failed" : ""}`}><h3><Target size={18}/>{invalid ? "失败分析与处置建议" : "计算结论"}</h3><p>{scenario.conclusion}</p><small>{invalid ? "失败任务的派生结果不能作为科研结论。" : "当前为油气炼化领域模拟数据，正式使用前需由专业人员复核。"}</small></section>;
  const files = <section className="sc-card sc-files"><h3><FileText size={18}/>任务文件 <small>共 {scenario.files.length} 个</small></h3><table className="sc-table"><thead><tr><th>文件名</th><th>大小</th><th>说明</th><th>操作</th></tr></thead><tbody>{scenario.files.map(file => <tr key={file.name}><td>{file.name}</td><td>{file.size}</td><td>{file.description}</td><td><button className="sc-link" onClick={() => downloadResult(task, file.name)}>下载</button></td></tr>)}</tbody></table></section>;
  const log = <section className="sc-card sc-log"><h3><FileText size={18}/>完整运行日志 <span><label>自动滚动 <input type="checkbox" checked={autoScroll} onChange={event => setAutoScroll(event.target.checked)}/></label><button onClick={() => downloadFile(`${task.id}-run.log`, scenario.log)}><Download size={15}/>下载日志</button></span></h3><pre>{scenario.log}</pre></section>;

  if (tab === "配置与运行") return <>{metricCards}<div className="sc-detail-grid"><div>{stageCard}</div><div>{parameterCard}{summary}</div></div></>;
  if (tab === "结果分析") return <div className="sc-detail-grid complete"><div>{resultChart}{dataTable}</div><div>{conclusion}</div></div>;
  if (tab === "文件与日志") return <div className="sc-result-only">{files}{log}</div>;
  return <>{metricCards}<div className="sc-overview-detail"><section className="sc-card sc-overview-primary"><h3><Activity size={18}/>任务状态与关键结论</h3><strong>{invalid ? "计算异常终止，当前结果无效" : complete ? "计算完成，结果等待专业复核" : "计算正在按领域流程执行"}</strong><p>{scenario.objective}</p><div className={`sc-domain-note${invalid ? " failed" : ""}`}>{scenario.conclusion}</div></section><section className="sc-card sc-overview-links"><h3><Target size={18}/>查看完整信息</h3><Link href="?tab=配置与运行">输入、配置与运行阶段 <ChevronRight size={14}/></Link><Link href="?tab=结果分析">领域指标与结果分析 <ChevronRight size={14}/></Link><Link href="?tab=文件与日志">任务文件与完整日志 <ChevronRight size={14}/></Link></section></div></>;
}

function TaskDetail({ task, tab, autoScroll, setAutoScroll, downloadResult }: { task: ComputingTask; tab: ComputingDetailTab; autoScroll: boolean; setAutoScroll: (value: boolean) => void; downloadResult: (task: ComputingTask, name?: string) => void }) {
  if (task.category === "compute") return <RefineryTaskDetail task={task} tab={tab} autoScroll={autoScroll} setAutoScroll={setAutoScroll} downloadResult={downloadResult}/>;
  return <ModelTaskDetail task={task} tab={tab} downloadResult={downloadResult}/>;
}

function LegacyTaskDetail({ task, tab, autoScroll, setAutoScroll, downloadResult }: { task: ComputingTask; tab: ComputingDetailTab; autoScroll: boolean; setAutoScroll: (value: boolean) => void; downloadResult: (task: ComputingTask, name?: string) => void }) {
  if (task.category !== "compute") return <ModelTaskDetail task={task} tab={tab} downloadResult={downloadResult}/>;
  const complete = task.status === "已完成";
  const rows = [["ENCUT", "350 eV", "已完成", "32", "-526.3421", "12.6", "00:38:21"], ["ENCUT", "400 eV", "已完成", "28", "-526.3518", "5.4", "00:42:17"], ["ENCUT", "450 eV", "已完成", "24", "-526.3549", "2.1", "00:46:03"], ["ENCUT", "500 eV", complete ? "已完成" : "运行中", complete ? "46" : "18 (/)", "-526.3561", complete ? "0.0" : "—", "01:12:28"], ["ENCUT", "550 eV", complete ? "已完成" : "排队中", complete ? "47" : "—", "-526.3563", "0.2", "—"], ["KPOINTS", "3 × 3 × 1", "已完成", "26", "-526.3482", "8.3", "00:35:12"], ["KPOINTS", "4 × 4 × 1", "已完成", "22", "-526.3540", "2.9", "00:48:21"], ["KPOINTS", "5 × 5 × 1", complete ? "已完成" : "排队中", complete ? "46" : "—", complete ? "-526.3561" : "—", complete ? "0.0" : "—", "—"]];
  const files = [["OUTCAR", "12.4 MB", "输出文件"], ["OSZICAR", "2.1 MB", "SCF 收敛信息"], ["CONTCAR", "258 KB", "优化后结构"], ["vasprun.xml", "8.7 MB", "详细计算结果"], ["INCAR", "1.2 KB", "输入参数"], ["KPOINTS", "0.5 KB", "K 点设置"], ["POSCAR", "1.1 KB", "初始结构"], ["CHGCAR", "15.6 MB", "电荷密度"]];
  const stats = complete ? [["总运行时长", "6 小时 13 分钟", "2024-07-28 10:24 - 16:37"], ["子任务完成", "12 / 12", "全部计算完成"], ["推荐参数组合", "ENCUT 500 eV", "KPOINTS 5 × 5 × 1"], ["结果文件", "8 个", "包含结构文件、能量数据等"]] : [["总体进度", `${task.progress}%`, "已完成 8 / 12 个子任务"], ["CPU", "72%", "计算资源占用"], ["内存", "65%", "计算资源占用"], ["GPU", "36%", "计算资源占用"]];
  const chart = <section className="sc-card sc-chart"><h3><Activity size={18}/>{complete ? "ENCUT 收敛性分析" : "实时收敛曲线"}<small>{complete ? "不同截断能下的总能量变化（以 500 eV 为参考）" : "当前子任务：ENCUT 500 eV，KPOINTS 5 × 5 × 1"}</small></h3><div className="sc-chart-body"><ResponsiveContainer width="100%" height={260}><LineChart data={graphData(task)} margin={{ top: 10, right: 15, left: 5, bottom: 10 }}><CartesianGrid stroke="#e5edf8"/><XAxis dataKey="step" tick={{fontSize:11,fill:"#5f779b"}} label={{value:"SCF Iteration",position:"insideBottom",offset:-5,fill:"#45648e",fontSize:11}}/><YAxis domain={["dataMin - 0.01", "dataMax + 0.01"]} tick={{fontSize:11,fill:"#5f779b"}} width={64}/><Tooltip formatter={(value) => [`${Number(value).toFixed(4)} eV`, "Total Energy"]}/><Line type="monotone" dataKey="energy" stroke="#086cf7" strokeWidth={2} dot={{r:2}} isAnimationActive={false}/></LineChart></ResponsiveContainer><dl><div><dt>当前迭代</dt><dd>18 / 40</dd></div><div><dt>当前能量</dt><dd>-526.3561 eV</dd></div><div><dt>能量变化</dt><dd>1.2 × 10⁻⁵ eV</dd></div><div><dt>收敛阈值</dt><dd>1.0 × 10⁻⁵ eV</dd></div><div><dt>预计剩余</dt><dd>{complete ? "已完成" : "约 25 分钟"}</dd></div></dl></div></section>;
  const scan = <section className="sc-card sc-scan"><h3><FileText size={18}/>参数扫描{complete ? "结果" : "进度"} <small>（8 / 12）</small></h3><div className="sc-table-scroll"><table className="sc-table"><thead><tr>{["#", "参数类型", "参数值", "状态", "SCF迭代", "总能量 (eV)", "ΔE (meV/atom)", "耗时"].map(h => <th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map((row, i) => <tr key={i} className={i === 3 ? "highlight" : ""}><td>{i + 1}</td>{row.map((v, j) => <td key={j}>{v}</td>)}</tr>)}</tbody></table></div></section>;
  const summary = <section className="sc-card sc-summary"><h3><FileText size={18}/>计算摘要</h3><dl>{[["计算软件", task.software || "VASP 6.4.2"], ["计算类型", task.type], ["计算体系", task.name.includes("PtNi") ? "PtNi(111) 表面 *CO 吸附" : task.name], ["计算资源", task.resource ?? "高性能计算集群"], ["计算节点", "2 × 计算节点"], ["运行时长", task.duration ?? "6 小时 13 分钟"], ["作业队列", "normal"], ["工作目录", "/data/ptni_co_dft/"], ["项目备注", task.note || "PtNi合金催化剂表面 CO 吸附能及电子结构分析"]].map(([k,v]) => <div key={k}><dt>{k}</dt><dd>{v}</dd></div>)}</dl></section>;
  const resultFiles = <section className="sc-card sc-files"><h3><FileText size={18}/>结果文件 <small>共 {files.length} 个文件</small></h3><table className="sc-table"><thead><tr><th>文件名</th><th>大小</th><th>说明</th><th>操作</th></tr></thead><tbody>{files.map(([name,size,description]) => <tr key={name}><td>{name}</td><td>{size}</td><td>{description}</td><td><button className="sc-link" onClick={() => downloadResult(task,name)}>下载</button></td></tr>)}</tbody></table></section>;
  const log = <section className="sc-card sc-log"><h3><FileText size={18}/>实时运行日志 <span><label>自动滚动 <input type="checkbox" checked={autoScroll} onChange={e => setAutoScroll(e.target.checked)}/></label><button onClick={() => downloadFile(`${task.id}-log.txt`, logText(task))}><Download size={15}/>下载日志</button></span></h3><pre>{logText(task)}</pre></section>;
  const currentConfig = <section className="sc-card sc-config"><h3><Target size={18}/>当前计算参数</h3><dl><div><dt>参数类型</dt><dd>ENCUT + KPOINTS</dd></div><div><dt>ENCUT</dt><dd>{task.encut ?? "500"} eV</dd></div><div><dt>KPOINTS</dt><dd>{task.kpoints ?? "5 × 5 × 1"}</dd></div><div><dt>EDIFF</dt><dd>{task.ediff ?? "1e-5"}</dd></div><div><dt>PREC</dt><dd>Accurate</dd></div><div><dt>ISMEAR</dt><dd>0</dd></div></dl></section>;
  const environment = <section className="sc-card sc-summary"><h3><Cpu size={18}/>运行环境</h3><dl><div><dt>计算集群</dt><dd>AI4S-HPC</dd></div><div><dt>计算节点</dt><dd>node032 (192.168.1.32)</dd></div><div><dt>CPU</dt><dd>32 核</dd></div><div><dt>GPU</dt><dd>2 × NVIDIA A100 (40GB)</dd></div><div><dt>内存</dt><dd>256 GB</dd></div><div><dt>运行环境</dt><dd>{task.software || "VASP"} · Linux</dd></div></dl></section>;
  const recommendation = <section className="sc-card sc-recommend"><h3><Settings2 size={18}/>推荐计算参数</h3><p>基于收敛性分析的推荐参数</p><dl><div><dt>ENCUT</dt><dd>500 eV</dd></div><div><dt>KPOINTS</dt><dd>5 × 5 × 1</dd></div><div><dt>EDIFF</dt><dd>1.0 × 10⁻⁵ eV</dd></div><div><dt>PREC</dt><dd>Accurate</dd></div></dl><div className="sc-ai-note">AI 分析结论：在 ENCUT = 500 eV 和 KPOINTS = 5 × 5 × 1 时，总能量已收敛，能够满足示例计算精度要求。</div></section>;
  const kpointsChart = <section className="sc-card sc-chart"><h3><Target size={18}/>KPOINTS 收敛性分析</h3><ResponsiveContainer width="100%" height={260}><LineChart data={[{step:"3×3×1",delta:25.4},{step:"4×4×1",delta:7.1},{step:"5×5×1",delta:0},{step:"6×6×1",delta:0.1}]}><CartesianGrid stroke="#e5edf8"/><XAxis dataKey="step" tick={{fontSize:11}}/><YAxis tick={{fontSize:11}}/><Tooltip/><Line dataKey="delta" stroke="#0969f6" strokeWidth={2} isAnimationActive={false}/></LineChart></ResponsiveContainer></section>;

  if (tab === "配置与运行") return <><div className="sc-stat-grid">{stats.map(([label,value,sub]) => <div className="sc-stat" key={label}><Clock3 size={22}/><span>{label}</span><strong>{value}</strong><small>{sub}</small></div>)}</div><div className="sc-detail-grid"><div>{scan}</div><div>{currentConfig}{summary}{environment}</div></div></>;
  if (tab === "结果分析") return complete ? <div className="sc-detail-grid complete"><div><div className="sc-two-charts">{chart}{kpointsChart}</div>{scan}</div><div>{recommendation}</div></div> : <div className="sc-detail-grid"><div>{chart}</div><div>{recommendation}</div></div>;
  if (tab === "文件与日志") return <div className="sc-result-only">{complete ? resultFiles : <section className="sc-card sc-files"><h3><FileText size={18}/>结果文件</h3><p className="sc-empty-note">任务完成后将在这里生成并归档结果文件。</p></section>}{log}</div>;
  return <><div className="sc-stat-grid">{stats.map(([label,value,sub]) => <div className="sc-stat" key={label}>{complete ? <CheckCircle2 size={22}/> : <Cpu size={22}/>}<span>{label}</span><strong>{value}</strong><small>{sub}</small>{label === "总体进度" && <i className="sc-meter"><b style={{width:`${task.progress}%`}}/></i>}</div>)}</div><div className="sc-overview-detail"><section className="sc-card sc-overview-primary"><h3><Activity size={18}/>任务状态与关键结论</h3><strong>{complete ? "计算已完成，结果等待科研人员复核" : task.status === "失败" ? "任务执行失败，需要检查配置后重试" : "任务正在执行，当前运行状态正常"}</strong><p>{complete ? "推荐参数组合为 ENCUT 500 eV、KPOINTS 5 × 5 × 1。当前内容为模拟结果，不能直接作为科学结论。" : task.status === "失败" ? "失败任务不会产生有效计算结论。请先检查运行配置与完整日志，再决定是否重试。" : `当前完成度 ${task.progress}%，可在“配置与运行”查看子任务进展。`}</p></section><section className="sc-card sc-overview-links"><h3><Target size={18}/>查看完整信息</h3><Link href="?tab=配置与运行">配置、资源与运行进度 <ChevronRight size={14}/></Link><Link href="?tab=结果分析">收敛曲线与参数分析 <ChevronRight size={14}/></Link><Link href="?tab=文件与日志">结果文件与完整日志 <ChevronRight size={14}/></Link></section></div></>;
}

function logText(task: ComputingTask) { return `[本地模拟日志] ${task.name}\n[2024-07-31 16:52:10] Reading WAVECAR ...\n[2024-07-31 16:52:11] start iteration 14\nDAV: 1  energy -526.355483  dE = -0.002314\nDAV: 2  energy -526.356021  dE = -0.000538\nDAV: 3  energy -526.356112  dE = -0.000091\n[2024-07-31 16:52:36] iteration 14 not converged\n[2024-07-31 16:53:02] start iteration 15\nDAV: 1  energy -526.356143  dE = -0.000031\nDAV: 2  energy -526.356155  dE = -0.000012\n[2024-07-31 16:53:18] iteration 15 converged\n[2024-07-31 16:53:18] writing charge density ...\n[2024-07-31 16:53:20] total cpu time : 1256.4 s`; }
